	/** The mixer category upstream gives this event, or {@link SoundSource#MASTER}. */
	public static SoundSource sourceOf(String key) {
		return SOURCES.getOrDefault(key, SoundSource.MASTER);
	}

	private static DeferredHolder<SoundEvent, SoundEvent> reg(String key) {
		ResourceLocation id = ResourceLocation.fromNamespaceAndPath(LeafiaRef.MODID, key);
		return SOUNDS.register(key, () -> SoundEvent.createVariableRangeEvent(id));
	}

	public static void register(IEventBus modBus) {
		SOUNDS.register(modBus);
	}
